"""Generate dependency-free C++/Python/Web catalogs from locales/fr.json."""
import argparse
import json
from pathlib import Path
import re

ROOT = Path(__file__).resolve().parents[1]


def outputs():
    english = json.loads((ROOT/'locales/en.json').read_text(encoding='utf8'))['translations']
    french = json.loads((ROOT/'locales/fr.json').read_text(encoding='utf8'))['translations']
    if set(english) != set(french):
        raise ValueError('English and French keys must match')
    printf = re.compile(r'%(?!%)(?:[-+ #0]*\d*(?:\.\d+)?(?:ll|l|z)?[a-zA-Z])')
    for key, value in french.items():
        if not isinstance(value, str) or printf.findall(english[key]) != printf.findall(value):
            raise ValueError(f'Invalid translation or printf placeholders: {key}')
    literal = lambda value: json.dumps(value, ensure_ascii=False)
    return {
        ROOT/'include/cyui/detail/LocaleFrench.inc': '// Generated by tools/generate_locales.py. Edit locales/fr.json.\n'+''.join(
            f'CYUI_TRANSLATION({literal(key)}, {literal(value)})\n' for key, value in sorted(french.items())),
        ROOT/'python/cyui_modules/_locale_catalog.py': '# Generated by tools/generate_locales.py. Edit locales/fr.json.\nFRENCH = '+json.dumps(french, ensure_ascii=False, indent=4, sort_keys=True)+'\n',
        ROOT/'web/cyui-locales.js': '// Generated by tools/generate_locales.py. Edit locales/fr.json.\nexport const french = '+json.dumps(french, ensure_ascii=False, indent=2, sort_keys=True)+';\n',
    }


if __name__ == '__main__':
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--check', action='store_true')
    args = parser.parse_args()
    for path, content in outputs().items():
        if args.check:
            if not path.is_file() or path.read_text(encoding='utf8') != content:
                raise SystemExit(f'Outdated generated catalog: {path.relative_to(ROOT)}')
        else:
            path.parent.mkdir(parents=True, exist_ok=True)
            path.write_text(content, encoding='utf8', newline='\n')
